def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Uniform full rows/columns mark the separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def regions(n, separators):
        bounds = [-1] + separators + [n]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_regions = regions(h, sep_rows)
    col_regions = regions(w, sep_cols)

    chambers = []
    for r0, r1 in row_regions:
        for c0, c1 in col_regions:
            if r0 < r1 and c0 < c1:
                score = sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
                chambers.append((score, r0, r1, c0, c1))

    _, r0, r1, c0, c1 = max(chambers)
    pattern = [row[c0:c1] for row in grid[r0:r1]]
    out = [row[:] for row in grid]

    for a, b in row_regions:
        for x, y in col_regions:
            if b - a == len(pattern) and y - x == len(pattern[0]):
                for dr in range(len(pattern)):
                    for dc in range(len(pattern[0])):
                        out[a + dr][x + dc] = pattern[dr][dc]
    return out
